// === Tab: mySketch.js ===
// Hello Raphaël,
//
// first of all, the interesting thing about this script is that it renders the shader with full pixel density,
// i.e. the screen dimensions are multiplied by the 'devicePixelRatio' factor.
// You still need to call the 'pixelDensity(1)' function (it's a hack, tbh).
// 
// The shader itself represents branches without branching. There are no conditionals. Or maybe there are?
// Ok, the function 'abs(x)' can be rewritten as max(x,-x) and max(a,b) can be rewritten as if (a > b) return a; else return b;
// So there you have it - branching. But not explicitly. ;-)

let theShader, dpr = window.devicePixelRatio, ww = window.innerWidth*dpr, wh = window.innerHeight*dpr;
const canvasStyle = 'width:100%;height:auto;touch-action:none;object-fit:contain;'

p5.RendererGL.prototype._initContext = function() {
	try { this.drawingContext = this.canvas.getContext('webgl2', this._pInst._glAttributes) ||
			this.canvas.getContext('experimental-webgl', this._pInst._glAttributes);
		if (this.drawingContext === null) { throw new Error('Error creating webgl context');
		} else { const gl = this.drawingContext; gl.enable(gl.DEPTH_TEST); gl.depthFunc(gl.LEQUAL);
			gl.viewport(0, 0, ww, wh);
			this._viewport = this.drawingContext.getParameter(this.drawingContext.VIEWPORT);
		} } catch (er) { throw er; }
};

function windowResized() {
	ww = window.innerWidth*dpr; wh = window.innerHeight*dpr;
  resizeCanvas(ww, wh);
	const canvas = document.querySelector('canvas');
	canvas.style = canvasStyle;
}

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/2400383/files/vert.glsl', 'frag.glsl');
}

function setup() {
  // disables scaling for retina screens which can create inconsistent scaling between displays
  pixelDensity(1);
  createCanvas(ww, wh, WEBGL);
	var canvas = document.querySelector('canvas');
	canvas.style = canvasStyle;
}

function draw() {
  // shader() sets the active shader with our shader
  shader(theShader);

  // here we're using setUniform() to send our uniform values to the shader
  theShader.setUniform("u_resolution", [width, height]);
  theShader.setUniform("u_time", millis() / 1000.0);

  // rect gives us some geometry on the screen
  rect(0,0,width,height);
}


// === Tab: vert.glsl ===
#version 300 es 
in vec4 aPosition;
void main() { gl_Position = aPosition*2.-1.; }

// === Tab: frag.glsl ===
#version 300 es
precision highp float;
out vec4 O;
uniform vec2 u_resolution;
uniform float u_time;
uniform vec3 u_mouse;
#define FC gl_FragCoord.xy
#define R u_resolution
#define T (u_time*2.) // speeds-up global time
#define S smoothstep
// returns a color for a given value (which differs by scene)
#define hue(a) (.25+.6*cos((6.3+1.35*floor(mod(tt, scenes)))*(a)+vec3(0,83,21)))
// returns the luminocity of a given color
#define lum(a) dot(vec3(.21,.71,.07),a)
#define tt (T*.1)
#define scenes 5.
// a value between 0 and scenes, which will change in the frequency of tt
#define proc floor(mod(tt,scenes))
// randomizes the given 2d value
vec2 rnd(vec2 p) {
  vec3 q=fract(vec3(p.x*12.9898,p.y*78.233,dot(p,p+34.56)));
  q+=dot(q,q+34.56);
  return fract(vec2(q.x*q.y,q.y*q.z));
}
void main(void) {
  vec2 uv = (FC-.5*R)/min(R.x, R.y),
  p = uv*1.5;
  uv *= 1.5-proc*.031;
  float k = (.805-.05*proc),
  f = pow(-log(tanh((.2+mod(T, 10.)*.2)))*.5, 5.);
  for (float i = .0; i++ <= 8.;) {
    uv = sqrt(abs(uv)/dot(uv, uv))-k+f;
		// Only if the code absolutely requires an explicit case distinction.
		// By the way, this also gives nice additional patterns. Just give it a try.
    //if (dot(uv,uv) < .0025*(.2-proc*.1)) break;
  }
	// calculation of the distance to a circle at UV, which has been distorted in the loop above
	// (the smoothstep function (S) stretches the value's range - change 1.8 to smthng up to 3.8
	// for different colors) and blur the result to smooth the fine lines
  float d = S(1.8+k*.2, -1.,length(uv+mix(vec2(.125),vec2(.35),rnd(p))))-k*2.;
  vec3 col = vec3(0);
	// colorize (multiplication with the fract part gives the steps)
  col += 1.2*hue(.9+d)*max(.075,fract(max(abs(p.y), abs(p.x))*5.));
	// color grading (makes darker parts darker)
  col /= 1.+exp(-col);
	// brightens the center
  col = sqrt(col+lum(col))+S(.25,-.1,length(p));
	// vignette
  p = (FC-.5*R)/R;
  col = mix(vec3(0), col, pow(S(.5,.07, dot(p*p, p*p)), 16.));
	// write the pixel's color
  O = vec4(col, 1);
}

